package com.messaging.consumer

import java.util.concurrent.{ConcurrentHashMap, ConcurrentLinkedQueue, Executors, TimeUnit}
import java.util.concurrent.atomic.{AtomicInteger, AtomicLong}
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

case class Message(id: String, payload: String, priority: Int, timestamp: Long)
case class ProcessingResult(messageId: String, success: Boolean, retryCount: Int)

trait MessageBroker {
  def acknowledge(messageId: String): Unit
  def reject(messageId: String): Unit
  def publish(queue: String, message: Message): Unit
}

class RateLimiter(maxRequests: Int, windowMs: Long) {
  private val timestamps = new ConcurrentLinkedQueue[Long]()
  private val counter = new AtomicInteger(0)

  def tryAcquire(): Boolean = {
    val now = System.currentTimeMillis()
    pruneExpired(now)
    // Atomic reservation of a slot to avoid check-then-act (TOCTOU) race
    // that could allow exceeding maxRequests under concurrency.
    var current = counter.get()
    while (current < maxRequests) {
      if (counter.compareAndSet(current, current + 1)) {
        timestamps.offer(now)
        return true
      }
      current = counter.get()
    }
    false
  }

  private def pruneExpired(now: Long): Unit = {
    var head = timestamps.peek()
    while (head != null && (now - head) > windowMs) {
      if (timestamps.remove(head)) {
        counter.decrementAndGet()
      }
      head = timestamps.peek()
    }
  }
}

class RetryPolicy(maxRetries: Int, baseDelayMs: Long) {
  private val retryCounters = new ConcurrentHashMap[String, AtomicInteger]()

  def shouldRetry(messageId: String): Boolean = {
    val counter = retryCounters.computeIfAbsent(messageId, _ => new AtomicInteger(0))
    counter.get() < maxRetries
  }

  def recordRetry(messageId: String): Int = {
    val counter = retryCounters.computeIfAbsent(messageId, _ => new AtomicInteger(0))
    counter.incrementAndGet()
  }

  def getDelay(messageId: String): Long = {
    val count = retryCounters.getOrDefault(messageId, new AtomicInteger(0)).get()
    baseDelayMs * (1L << Math.min(count, 6))
  }

  def clearRetry(messageId: String): Unit = {
    retryCounters.remove(messageId)
  }
}

class MessageConsumer(
  broker: MessageBroker,
  rateLimiter: RateLimiter,
  retryPolicy: RetryPolicy,
  deadLetterQueue: String
) {
  private val processingState = new ConcurrentHashMap[String, Long]()
  private val claimRegistry = new ConcurrentHashMap[String, String]()
  private val executor = Executors.newScheduledThreadPool(4)
  private val sequenceCounter = new AtomicLong(0)

  def consume(message: Message, consumerId: String): ProcessingResult = {
    val claimToken = generateClaimToken(consumerId, message.id)

    // Register claim before rate limit check
    val existingClaim = claimRegistry.putIfAbsent(message.id, claimToken)
    if (existingClaim != null && existingClaim != claimToken) {
      return ProcessingResult(message.id, false, 0)
    }

    if (!rateLimiter.tryAcquire()) {
      // Rate limited - release claim and schedule retry
      claimRegistry.remove(message.id, claimToken)
      scheduleRetry(message, consumerId)
      return ProcessingResult(message.id, false, retryPolicy.recordRetry(message.id))
    }

    // Mark as processing
    processingState.put(message.id, System.currentTimeMillis())

    try {
      val result = processMessage(message)
      if (result) {
        broker.acknowledge(message.id)
        retryPolicy.clearRetry(message.id)
        ProcessingResult(message.id, true, 0)
      } else {
        handleFailure(message, consumerId, claimToken)
      }
    } catch {
      case e: Exception =>
        handleFailure(message, consumerId, claimToken)
    } finally {
      processingState.remove(message.id)
    }
  }

  private def handleFailure(message: Message, consumerId: String, claimToken: String): ProcessingResult = {
    val retryCount = retryPolicy.recordRetry(message.id)
    if (retryPolicy.shouldRetry(message.id)) {
      // Schedule retry while maintaining claim - prevents front-running
      scheduleRetry(message, consumerId)
      ProcessingResult(message.id, false, retryCount)
    } else {
      claimRegistry.remove(message.id, claimToken)
      broker.reject(message.id)
      sendToDeadLetter(message)
      retryPolicy.clearRetry(message.id)
      ProcessingResult(message.id, false, retryCount)
    }
  }

  private def scheduleRetry(message: Message, consumerId: String): Unit = {
    val delay = retryPolicy.getDelay(message.id)
    executor.schedule(
      new Runnable {
        override def run(): Unit = consume(message, consumerId)
      },
      delay,
      TimeUnit.MILLISECONDS
    )
  }

  private def processMessage(message: Message): Boolean = {
    // Simulate processing with validation
    message.payload.nonEmpty && message.priority >= 0
  }

  private def sendToDeadLetter(message: Message): Unit = {
    broker.publish(deadLetterQueue, message.copy(timestamp = System.currentTimeMillis()))
  }

  private def generateClaimToken(consumerId: String, messageId: String): String = {
    val seq = sequenceCounter.incrementAndGet()
    s"$consumerId-$messageId-$seq"
  }

  def getProcessingState: Map[String, Long] = {
    import scala.jdk.CollectionConverters._
    processingState.asScala.toMap
  }

  def shutdown(): Unit = {
    executor.shutdown()
    executor.awaitTermination(30, TimeUnit.SECONDS)
  }
}
